// In handle_envelope, replace J::parse(bytes_str(*pt)) with a depth-limited parse:
static constexpr int kMaxJsonDepth = 64;
int depth = 0, maxd = 0; bool ok = true;
J p = J::parse(bytes_str(*pt), [&](int d, J::parse_event_t e, J&){
  if (e == J::parse_event_t::object_start || e == J::parse_event_t::array_start) maxd = std::max(maxd, ++depth);
  else if (e == J::parse_event_t::object_end || e == J::parse_event_t::array_end) --depth;
  if (maxd > kMaxJsonDepth) { ok = false; return false; }
  return true;
}, /*allow_exceptions=*/false);
